def looks_chinese(text: str) -> bool:
    return bool(CHINESE_RE.search(text or ""))


def is_cnki_url(url: str) -> bool:
    try:
        return bool(CNKI_HOST_RE.search(urllib.parse.urlparse(url).hostname or ""))
    except Exception:  # noqa: BLE001
        return False


def cnki_search_url(query: str, base: str = DEFAULT_CNKI_SEARCH, db: str = "") -> str:
    """检索页 URL。`db` 非空时带 dbCode（CDFD 期刊 / CDFW 学位论文等）。"""
    u = urllib.parse.urlparse(base or DEFAULT_CNKI_SEARCH)
    q = dict(urllib.parse.parse_qsl(u.query))
    q["kw"] = query
    if db:
        q["dbCode"] = db
    return urllib.parse.urlunsplit((u.scheme, u.netloc, u.path,
                                    urllib.parse.urlencode(q), u.fragment))


def norm_title(s: str) -> str:
    """题名规范化：与 JS 探针里的 `NFKC + [\\s\\p{P}\\p{S}]+ → 去掉 + 小写` 同口径。

    JS 用 `\\p{P}\\p{S}`（所有标点与符号）。Python 侧用 unicodedata 的类别首字母
    P/S 加空白与控制符等价覆盖——**两边必须一致**，否则 JS 说"唯一命中"而
    Python 复核说不等，就会把能下的文章判成歧义。
    """
    out = []
    for ch in unicodedata.normalize("NFKC", s or ""):
        cat = unicodedata.category(ch)
        if cat[0] in ("P", "S", "Z", "C") or ch.isspace():
            continue
        out.append(ch.lower())
    return "".join(out)


def classify_cnki_wall(url: str, title: str, body: str) -> Optional[dict[str, str]]:
    """判断当前页面是不是知网侧的墙；不是墙返回 None。"""
    text = f"{title}\n{body}"
    if WALL_SLIDER.search(text):
        return {"status": "captcha_requires_human",
                "reason": "CNKI 滑块验证（本工具不自动破解）"}
    if WALL_DENIED.search(text):
        return {"status": "paywalled", "reason": "CNKI 无下载权限/未订购"}
    if WALL_LOGIN.search(text):
        return {"status": "paywalled", "reason": "CNKI 或机构需要登录（先用 --login 过统一身份认证）"}
    return None


def score_candidate(text: str, url: str) -> int:
    """下载候选优先级：PDF > 一般下载 > CAJ > 其他（与 cnki.mjs:164-170 同序）。"""
    s = f"{text} {url}"
    if re.search(r"pdf", s, re.I):
        return 0
    if re.search(r"caj", s, re.I):
        return 2        # CAJ 要先转换，所以排在"直接下载"后面（能拿 PDF 就不碰它）
    if re.search(r"下载|download", s, re.I):
        return 1
    return 3


def filter_candidates(cands: list[dict[str, str]], fmt: str = "pdf") -> list[dict[str, Any]]:
    """按格式过滤 + 稳定排序 + 附上打分与推断扩展名。

    fmt=pdf：只留 PDF 候选（默认，最省事，直接进提取链）；
    fmt=caj：只留 CAJ 候选（明知要转换，用于只有 CAJ 的学位论文）；
    fmt=any：全留，命中哪个算哪个（PDF 优先）。
    """
    out: list[dict[str, Any]] = []
    seen: set[str] = set()
    for c in cands or []:
        url = (c.get("url") or "").strip()
        if not url or url in seen or not is_cnki_url(url):
            continue
        seen.add(url)
        text = c.get("text") or ""
        is_pdf = bool(re.search(r"pdf", f"{text} {url}", re.I))
        is_caj = bool(re.search(r"caj", f"{text} {url}", re.I))
        if fmt == "pdf" and not is_pdf:
            continue
        if fmt == "caj" and not is_caj:
            continue
        out.append({"url": url, "text": text, "score": score_candidate(text, url),
                    "ext": ".pdf" if (is_pdf and not (is_caj and not is_pdf)) else ".caj"})
    out.sort(key=lambda x: (x["score"], x["url"]))
    return out


def guess_ext(buf: bytes, url: str = "", ctype: str = "") -> str:
    """按字节头猜类型：pdf / caj / html / bin。"""
    head = (buf or b"")[:600]
    if head.startswith(b"%PDF-"):
        return "pdf"
    if HTML_HEAD_RE.match((head[:200] or b"").decode("utf-8", "replace")):
        return "html"
    low = f"{url} {ctype}".lower()
    if "caj" in low:
        return "caj"
    # CAJ 容器常见头（%TBS / CAJ / PNRS）；认不出就当 bin，交给 caj_to_pdf 复判
    if any(h in head[:16] for h in (b"%TBS", b"CAJ", b"PNRS")):
        return "caj"
    return "bin"


def pick_unique_match(links: list[dict[str, str]], title: str) -> tuple[Optional[dict[str, str]], str]:
    """在结果链接里挑**规范化后完全相等且唯一**的详情页。

    返回 (命中, 原因)。上游在多篇命中时只回 null；这里把原因带出来，
    残余清单才能告诉用户"去人工挑一篇"，而不是笼统一句失败。
    """
    want = norm_title(title)
    if not want:
        return None, "no_title"
    det = [x for x in (links or [])
           if re.search(r"detail|kcms|kns8s|dbcode|filename", (x.get("href") or ""), re.I)
           and is_cnki_url(x.get("href") or "")]
    exact = [x for x in det if norm_title(x.get("text") or "") == want]
    if len(links or []) >= _RESULT_SCAN_CAP:
        # 触到 JS 扫描上限：后面可能还有没扫到的同名条目，此时"唯一命中"不可信。
        # 原来 slice(0, 30) + 只数前 30 条 = 第 31 条之后的同名完全看不见（R1 破口）。
        return None, (f"ambiguous（结果链接触到扫描上限 {_RESULT_SCAN_CAP}，"
                      "无法确认题名唯一，请人工核对）")
    if len(exact) == 1:
        return exact[0], "ok"
    if not exact:
        return None, f"no_exact_match（详情页候选 {len(det)} 条）"
    return None, f"ambiguous（题名完全相同的候选 {len(exact)} 条，不猜）"


