_BULLET_RE = re.compile(r"^\s*(?:[-*+•]|\d+[.)、]|\|)\s*")


def titles_from_text(text: str) -> list[str]:
    """从 md/txt/TSV 里抽题名。跳过标题行、引用行、表格分隔行与纯 URL 行。"""
    out: list[str] = []
    for raw in (text or "").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or line.startswith(">"):
            continue
        if set(line) <= set("|-: "):          # markdown 表格分隔行
            continue
        if line.startswith("|"):              # 表格行：取第一个非空单元格
            cells = [c.strip() for c in line.strip("|").split("|")]
            line = next((c for c in cells if c and not re.match(r"^https?://", c)), "")
        line = _BULLET_RE.sub("", line).strip().strip("|").strip()
        line = re.sub(r"^\*\*(.*)\*\*$", r"\1", line).strip()
        if len(line) < 4 or re.match(r"^(https?://\S+|doi:\S+|10\.\d{4,}/\S+)$", line, re.I):
            continue
        out.append(line)
    return out


def items_from_input(path: str) -> list[bf.Item]:
    """支持三种输入：fetch_result/picks 的 JSON、纯文本题名清单、TSV。"""
    text = bf._read_text(path)
    items: list[bf.Item] = []
    if path.lower().endswith(".json"):
        try:
            data = json.loads(text.lstrip("\ufeff"))
        except Exception as e:  # noqa: BLE001
            raise SystemExit(f"[错误] 不是合法 JSON：{path}（{e}）")
        recs = data.get("papers") if isinstance(data, dict) else data
        if isinstance(data, dict) and not recs:
            recs = data.get("items") or data.get("results") or []
        for rec in recs or []:
            if not isinstance(rec, dict):
                continue
            t = (rec.get("title") or rec.get("Title") or "").strip()
            if not t:
                continue
            items.append(bf.Item(title=t, journal=rec.get("journal") or "",
                                 publication_date=rec.get("publication_date") or "",
                                 source="cnki-in", recipe=RATE_DOMAIN))
        return items
    if "\t" in text:
        for line in text.splitlines():
            cells = [c.strip() for c in line.split("\t") if c.strip()]
            if len(cells) >= 2 and cells[0].lower() in ("title", "题名", "篇名"):
                continue
            if cells:
                items.append(bf.Item(title=cells[0],
                                     journal=cells[1] if len(cells) > 1 else "",
                                     source="cnki-tsv", recipe=RATE_DOMAIN))
        return items
    for t in titles_from_text(text):
        items.append(bf.Item(title=t, source="cnki-list", recipe=RATE_DOMAIN))
    return items


def find_existing_by_title(title: str) -> str:
    """按规范化题名在 raw/pdf 里找已有主文（知网条目没有 DOI，只能按题名认）。"""
    want = norm_title(title)
    if len(want) < 8:
        return ""
    import glob as _glob
    for p in _glob.glob(os.path.join(VAULT, "raw", "pdf", "**", "*.pdf"), recursive=True):
        base = os.path.splitext(os.path.basename(p))[0]
        # 只认"题名段完全相等"。原来是双向子串（want in stem or stem in want），
        # 库里有《固态电解质界面研究进展与展望》就会把《固态电解质界面研究》判成
        # "已收录"直接 skip —— 静默漏下，正是 R1「绝不猜」要防的事。
        # 宁可漏判多下一次（可复核），不可误判 skip（无人知晓）。
        head = norm_title(base.split(" - ")[0])
        if head == want and bf.looks_pdf_file(p):
            return p
    return ""


# ---------------------------------------------------------------------------
# 抓取一步（异步；只在 run_cnki 里被调用）
# ---------------------------------------------------------------------------
async def _snapshot(page) -> dict[str, str]:
    try:
        s = await page.evaluate(JS_SNAPSHOT)
        return {"url": s.get("url") or "", "title": s.get("title") or "", "body": s.get("body") or ""}
    except Exception as e:  # noqa: BLE001
        return {"url": "", "title": "", "body": "", "err": f"{type(e).__name__}: {str(e)[:120]}"}


async def _eval_json(page, js: str, arg: Any = None) -> Any:
    """执行返回 JSON 字符串的探针；页面死了/返回垃圾都不抛。"""
    try:
        raw = await page.evaluate(js, arg) if arg is not None else await page.evaluate(js)
    except Exception:  # noqa: BLE001
        return None
    if raw is None or isinstance(raw, (list, dict)):
        return raw
    try:
        return json.loads(raw)
    except Exception:  # noqa: BLE001
        return None


async def _wall_or_pass(sess, page, item: bf.Item, where: str) -> Optional[dict[str, str]]:
    """页面若在墙上：交互模式等人过一次，无人值守直接把墙带回去。

    返回 None 表示"可以继续往下走"。这里**不自动破解滑块**：知网的滑块是
    明确的人机验证，破解它既越界也容易把 IP 送进风控（本库吃过这个亏，
    见 lit_browser_fetch 的 rate_policy 注释）。
    """
    snap = await _snapshot(page)
    wall = classify_cnki_wall(snap["url"], snap["title"], snap["body"])
    if not wall:
        st = await sess.detect_state(page)
        if st.get("hard_block"):
            return {"status": "paywalled", "reason": f"知网侧明确拒绝：{snap['title'][:40]}"}
        if st.get("challenge"):
            # 知网链**不走 pass_challenge**：它会程序化点 Cloudflare/hCaptcha/reCAPTCHA
            # 复选框（lit_browser_fetch:1753+，botmanager 还会按住 6–9 秒），那是"非人工
            # 通过验证"，与 R3「只用机构授权、不破解验证码」直接冲突，且风险由用户的机构
            # 账号承担。这里只等真人；无人值守一律 captcha_requires_human。
            if sess.interactive:
                print(f"[wall] {where}：{st['challenge']} 挑战页 → 等你在浏览器里过"
                      f"（{sess.human_timeout}s）")
                res, _ = await sess.wait_for_human(page, item)
                if res in ("ok", "human_ok"):
                    return None
                return {"status": res if res in bf.CHALLENGE_STATES else "captcha_requires_human",
                        "reason": f"{where}：{st['challenge']} 挑战页需真人（{res}）"}
            return {"status": "captcha_requires_human",
                    "reason": f"{where}：{st['challenge']} 挑战页（无人值守不处理）"}
        return None
    if not sess.interactive:
        return wall
    print(f"[wall] {where}：{wall['reason']} → 等你在浏览器里处理（{sess.human_timeout}s）")
    got, _ = await sess.wait_for_human(page, item)
    if got in ("ok", "human_ok"):
        return None
    return wall


async def _fetch_any(sess, page, url: str) -> tuple[Optional[bytes], str, dict[str, str]]:
    """页内 fetch 取任意字节（PDF 与 CAJ 都要）。拿不到再退回浏览器下载通道。"""
    try:
        res = await page.evaluate(JS_FETCH_BYTES, url)
    except Exception as e:  # noqa: BLE001
        res = None
        err = f"page_fetch_error: {type(e).__name__}: {str(e)[:100]}"
    else:
        err = ""
    if res and not res.get("too_big") and res.get("b64"):
        try:
            buf = base64.b64decode(res.get("b64") or "")
        except Exception as e:  # noqa: BLE001
            return None, f"base64_error: {e}", {}
        meta = {"ct": (res.get("ct") or "")[:60], "cd": (res.get("cd") or "")[:120],
                "status": str(res.get("status"))}
        return buf, "", meta
    if res and res.get("too_big"):
        # 大文件走浏览器自己的下载通道（与 lit_browser_fetch 处理 ACS SI 同法）
        buf, why = await sess.nav_download_bytes(page, url, os.path.join(VAULT, "_scratch"))
        if buf:
            return buf, "", {"via": "nav_download"}
        return None, f"too_big_and_nav_failed: {why}", {}
    if res:
        return None, f"page_fetch_empty(status={res.get('status')}, ct={(res.get('ct') or '')[:40]})", {}
    buf, why = await sess.nav_download_bytes(page, url, os.path.join(VAULT, "_scratch"))
    if buf:
        return buf, "", {"via": "nav_download"}
    return None, (err or f"nav_download_failed: {why}"), {}


def _convert_caj(caj_path: str, pdf_path: str) -> dict[str, Any]:
    try:
        import caj_to_pdf
        return caj_to_pdf.convert_one(caj_path, pdf_path)
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "reason": f"caj_to_pdf 不可用：{type(e).__name__}: {e}"}


async def _grab_si(sess, page, item: bf.Item, si_dir: str, stem: str,
                   gov: Any = None) -> tuple[str, list[str], str]:
    """扫详情页的补充材料链接并下载。非 HTML 才留，命名 `<主文 stem>.si.<ext>`。

    命名必须守库内约定：`raw/pdf/si` 现有 579 个文件 579/579 都是 `.si.<ext>`。
    用 `<stem>__<原名>` 的坏处有两条——`bf.existing_si_files()` 只认 `<stem>.si` 前缀，
    重跑必然重下重写；更要命的是 `lit_batch.walk_pdfs()` 只按 `.si.pdf` 后缀排除 SI，
    `__xxx.pdf` 会被当成**待提取主文**进 raw/text 甚至建卡。
    每个 SI 都过节奏治理（正文与 SI 各记一次），否则 cnki 日配额会被稀释成 7 倍。
    """
    links = await _eval_json(page, JS_FIND_SI_LINKS) or []
    if not isinstance(links, list) or not links:
        return "not_applicable", [], "详情页没找到补充材料链接"
    os.makedirs(si_dir, exist_ok=True)
    got: list[str] = []
    taken = set(bf.existing_si_files(si_dir, stem))
    slot = 1
    for i, href in enumerate(links[:6], 1):
        if gov is not None:
            blocked = gov.precheck(RATE_DOMAIN)
            if blocked:
                item.attempts.append(f"si 让位给节奏治理：{blocked}")
                break
            wait = gov.wait_seconds(RATE_DOMAIN)
            if wait > 0:
                await asyncio.sleep(wait)
        buf, why, _meta = await _fetch_any(sess, page, href)
        if gov is not None:
            gov.note(RATE_DOMAIN, "ok" if buf else "other", why or "")
        if not buf:
            continue
        ext = guess_ext(buf, href)
        if ext == "html":
            continue
        while True:                     # 跳过同名已存在，换 .si2./.si3.
            tag = ".si" if slot == 1 else f".si{slot}"
            slot += 1
            dest = os.path.join(si_dir, f"{stem}{tag}.{ext}")
            if dest not in taken:
                break
        try:
            bf._atomic_write(dest, buf)
            taken.add(dest)
            got.append(dest)
        except Exception as e:          # noqa: BLE001  写盘失败必须留痕，别静默丢
            item.attempts.append(f"si 写盘失败 {type(e).__name__}: {str(e)[:80]}")
            continue
    if got:
        return "present", got, ""
    return "missing", [], f"候选 {len(links)} 条都没拿到非 HTML 文件"


async def fetch_one(sess, page, item: bf.Item, opts: dict[str, Any]) -> None:
    """一篇知网条目：检索 → 唯一题名命中 → 详情页 → 下载 → （必要时）转 PDF → SI。

    只改 item 的状态字段，不抛异常——一篇的失败不能带走整批。
    """
    item.publisher = item.publisher or "中国知网"
    item.recipe = RATE_DOMAIN
    inbox, si_dir, caj_dir = opts["inbox"], opts["si_dir"], opts["caj_dir"]
    base_url = opts["cnki_url"]

    search = cnki_search_url(item.title, base_url, opts.get("cnki_db") or "")
    await sess.dismiss_cookies(page)
    _resp, why = await sess.goto(page, search)
    if why:
        item.status, item.reason = "failed", f"检索页打不开：{why}"
        item.attempts.append(f"search goto: {why}")
        return
    await asyncio.sleep(random.uniform(1.2, 2.4))
    await sess.idle(page, 1.0)
    await page.evaluate(JS_SEARCH_INJECT, item.title)
    await asyncio.sleep(random.uniform(2.0, 3.2))
    try:
        await page.wait_for_load_state("domcontentloaded", timeout=15000)
    except Exception:  # noqa: BLE001
        pass

    wall = await _wall_or_pass(sess, page, item, "检索结果页")
    if wall:
        item.status, item.reason = wall["status"], f"检索阶段：{wall['reason']}"
        return

    hits = await _eval_json(page, JS_FIND_RESULT) or []
    hit, why = pick_unique_match(hits if isinstance(hits, list) else [], item.title)
    if not hit:
        item.status, item.reason = "failed", f"题名检索：{why}"
        item.attempts.append(f"候选 {len(hits) if isinstance(hits, list) else 0} 条")
        return
    item.article_url_used = scrub_url(hit["href"])
    item.attempts.append(f"命中详情页：{hit['href'][:90]}")

    _resp, why = await sess.goto(page, hit["href"], referer=search)
    if why:
        item.status, item.reason = "failed", f"详情页打不开：{why}"
        return
    await asyncio.sleep(random.uniform(1.2, 2.2))
    snap = await _snapshot(page)
    if re.search(r"404|页面不存在|not found", f"{snap['title']} {snap['body']}", re.I):
        legacy = legacy_detail_url(hit)
        if legacy:
            await sess.goto(page, legacy)
            await asyncio.sleep(1.2)
            snap = await _snapshot(page)
    wall = await _wall_or_pass(sess, page, item, "详情页")
    if wall:
        item.status, item.reason = wall["status"], f"详情页：{wall['reason']}"
        return

    meta = await _eval_json(page, JS_DETAIL_META) or {}
    if isinstance(meta, dict):
        item.journal = item.journal or (meta.get("journal") or "")[:120] or "中国知网"
        d = (meta.get("date") or "").strip()
        m = re.search(r"(19|20)\d{2}", d)
        item.publication_date = item.publication_date or (f"{m.group(0)}-01-01" if m else "")
        if meta.get("doi"):
            item.doi = item.doi or meta["doi"][:80]
        if meta.get("authors") and not item.main_authors:
            item.main_authors = meta["authors"][:200]
        # R1 复核：命中判据本来只有"检索页链接文字相等"，链接文字与详情页真实条目
        # 可能不一致（v= 跳转、老入口串档）。这里用详情页题名再核一次。
        # 用双向包含而不是全等：知网详情页常在题名后挂期刊名/数据库名，全等会大面积
        # 误杀；而"两个方向都不包含"只可能是另一篇论文。
        got_t, want_t = norm_title(meta.get("title") or ""), norm_title(item.title)
        if got_t and want_t and want_t not in got_t and got_t not in want_t:
            item.status = "failed"
            item.reason = (f"题名不一致：详情页《{str(meta.get('title') or '')[:50]}》"
                           f"≠ 检索《{item.title[:50]}》，不下载")
            item.attempts.append("详情页题名与检索题名不匹配（R1 复核拦下）")
            return
    else:
        item.journal = item.journal or "中国知网"

    cands = await _eval_json(page, JS_FIND_DOWNLOADS) or []
    pick = filter_candidates(cands if isinstance(cands, list) else [], opts.get("cnki_format") or "pdf")
    if not pick:
        item.status = "failed"
        item.reason = (f"详情页没有 {opts.get('cnki_format')} 下载候选"
                       f"（原始候选 {len(cands) if isinstance(cands, list) else 0} 条；"
                       "只有 CAJ 时加 --cnki-format any）")
        return

    for cand in pick:
        buf, why, meta2 = await _fetch_any(sess, page, cand["url"])
        if not buf:
            item.attempts.append(f"{cand['text'][:16] or cand['url'][:40]} → {why}")
            continue
        kind = guess_ext(buf, cand["url"], meta2.get("ct") or "")
        if kind == "html":
            item.attempts.append(f"{cand['text'][:16] or '候选'} → 拿到的是网页（多半要登录）")
            continue
        stem = os.path.splitext(bf.filename_for(item))[0]
        if kind == "pdf" or (kind == "bin" and cand["ext"] == ".pdf"):
            dest = os.path.join(inbox, stem + ".pdf")
            ok2, why2 = await sess.save_pdf(dest, buf)
            if ok2:
                item.status, item.dest, item.size = "ok", dest, len(buf)
                item.method = "cnki_pdf"
                break
            item.attempts.append(f"PDF 落盘失败：{why2}")
            continue
        # CAJ（或认不出但候选写着 CAJ）：先落 _scratch，转换成功才进 raw/pdf
        os.makedirs(caj_dir, exist_ok=True)
        caj_path = os.path.join(caj_dir, stem + ".caj")
        try:
            bf._atomic_write(caj_path, buf)
        except Exception as e:  # noqa: BLE001
            item.attempts.append(f"CAJ 落盘失败：{e}")
            continue
        if not opts.get("convert_caj", True):
            item.status, item.reason = "failed", f"blocked_format：CAJ 留在 {bf._rel(caj_path)}（--no-caj-convert）"
            break
        pdf_out = os.path.join(inbox, stem + ".pdf")
        conv = _convert_caj(caj_path, pdf_out)
        if conv.get("ok"):
            if int(conv.get("bytes") or 0) > bf.MAX_PDF_BYTES:
                # 转换产物也是 PDF，一样受本库大小上限约束：移出 raw/pdf，原件留档待人工
                try:
                    os.replace(pdf_out, os.path.join(caj_dir, stem + ".oversize.pdf"))
                except OSError:
                    pass
                item.status = "failed"
                item.reason = (f"blocked_format：转换产物 {conv.get('bytes')} B 超上限 "
                               f"{bf.MAX_PDF_BYTES} B，已移出 raw/pdf")
                break
            item.status, item.dest, item.size = "ok", pdf_out, conv.get("bytes") or 0
            item.method = f"cnki_caj→pdf({conv.get('engine')}, {conv.get('pages')}页)"
            if not conv.get("has_text_layer"):
                item.attempts.append("转换产物没有文字层（扫描件式 CAJ）")
            if opts.get("keep_caj", True):
                # 原件默认留着：caj2pdf 官方口径是"佛系转换"，产物可能没文字层，
                # 日后引擎改进了还得能重转；scratch 已 gitignore，不污染库。
                # 想要旧行为（转成功就删）用 --delete-caj 或 cnki.keep_caj: false。
                item.attempts.append(f"CAJ 原件留档：{bf._rel(caj_path)}")
            else:
                try:
                    os.remove(caj_path)
                except OSError:
                    pass
            break
        item.status = "failed"
        item.reason = f"blocked_format：{conv.get('reason') or '转换失败'}；原件留在 {bf._rel(caj_path)}"
        break
    else:
        item.status = item.status or "failed"
        item.reason = item.reason or "所有下载候选都没拿到文件"

    if item.status == "ok" and not opts.get("no_si"):
        st, files, sr = await _grab_si(sess, page, item, si_dir,
                                       os.path.splitext(os.path.basename(item.dest))[0],
                                       gov=opts.get("gov"))
        item.si_status, item.si_files, item.si_reason = st, files, sr


# ---------------------------------------------------------------------------
# 输出：报告 / 残余清单
# ---------------------------------------------------------------------------
def legacy_detail_url(hit: dict[str, str]) -> str:
    """新-detail 页 404 时的老入口兜底（与 cnki.mjs:60-66 同法）。"""
    fn = (hit or {}).get("filename") or ""
    if not fn:
        return ""
    q = {"filename": fn}
    if (hit or {}).get("dbcode"):
        q["dbcode"] = hit["dbcode"]
    return "https://kns.cnki.net/kcms/detail/detail.aspx?" + urllib.parse.urlencode(q)


_DROP_QUERY_KEYS = ("v", "sign", "ts", "tok", "token", "sessid")


def scrub_url(url: str) -> str:
    """抹掉知网 URL 里的会话型令牌，再让它进报告/残余清单（这些目录进 git）。

    `kcms2/article/abstract?v=<长 base64>` 的 `v` 是会话令牌，连同机构侧访问路径原样
    提交进 `raw/notes/lit-watch/downloads/` 不合适（R3：机构授权不外泄）。
    `filename` / `dbcode` 是稳定标识，留着反而方便人工复现，所以只抹令牌类参数。
    """
    if not url or "?" not in url:
        return url
    try:
        parts = urllib.parse.urlsplit(url)
    except ValueError:
        return "<无法解析的链接>"
    kept = []
    for pair in parts.query.split("&"):
        if not pair:
            continue
        key = pair.split("=", 1)[0].lower()
        if key in _DROP_QUERY_KEYS:
            kept.append(f"{key}=<已隐去>")
        else:
            kept.append(pair)
    return urllib.parse.urlunsplit(parts._replace(query="&".join(kept)))


_CNKI_STATUS_LABEL = {
    "ok": "✅ 已下载",
    "failed": "❌ 失败",
    "skipped": "⏭️ 跳过",
    "paywalled": "🔒 需授权",
    "captcha_requires_human": "🧩 需人工验证",
}


def _fmt_row(it: Any) -> str:
    label = _CNKI_STATUS_LABEL.get(it.status, it.status or "…")
    tail = bf._rel(it.dest) if it.status == "ok" and it.dest else (it.reason or "")
    return f"| {label} | {it.title[:60]} | {tail} |"


def render_cnki_report(items: list[Any], *, input_path: str, mode: str, started: float,
                       inbox: str, caj_dir: str, residual_path: str = "") -> str:
    """紧凑报告：知网条目没有 DOI，按题名成表，DOI 版报告在这里反而看不清。"""
    ok = [x for x in items if x.status == "ok"]
    skipped = [x for x in items if x.status == "skipped"]
    todo = [x for x in items if x.status not in ("ok", "skipped")]
    lines = [
        "# 知网下载报告",
        "",
        f"- 输入：`{input_path}`",
        f"- 模式：{mode}　耗时：{time.time() - started:.0f}s　时间：{bf._now()}",
        f"- 落点：正文 `{bf._rel(inbox)}`　未转换 CAJ `{bf._rel(caj_dir)}`",
        f"- 结果：成功 **{len(ok)}**／待处理 **{len(todo)}**／跳过 {len(skipped)}",
        "",
    ]
    if ok:
        lines += ["## ✅ 已入库候选", "", "| 状态 | 题名 | 文件 |", "|---|---|---|"]
        lines += [_fmt_row(x) for x in ok]
        lines += [""]
    if todo:
        lines += ["## ❌ 待处理", "", "| 状态 | 题名 | 原因 |", "|---|---|---|"]
        lines += [_fmt_row(x) for x in todo]
        lines += [""]
    if skipped:
        lines += ["## ⏭️ 跳过", "", "| 状态 | 题名 | 原因 |", "|---|---|---|"]
        lines += [_fmt_row(x) for x in skipped]
        lines += [""]
    si_hit = [x for x in items if x.si_status == "present"]
    if si_hit:
        lines += [f"## 📎 补充材料：{len(si_hit)} 篇拿到，共 "
                  f"{sum(len(x.si_files) for x in si_hit)} 个文件", ""]
    if residual_path:
        lines += [f"残余清单：`{bf._rel(residual_path)}`", ""]
    lines += ["> 知网条目**没有 DOI**，入库文件名口径是 `题名 - 刊名 - 年.pdf`；",
              "> 只有 CAJ 的学位论文若转换失败，原件留在上面的 CAJ 目录，",
              "> 可随时用 `python tools/caj_to_pdf.py --batch <该目录>` 重试。", ""]
    return "\n".join(lines)


def write_cnki_residual(items: list[Any], path: str, inbox: str) -> str:
    """需要人工的条目（登录墙/滑块/题名歧义/CAJ 转不动）写成可勾选清单。

    不复用 `lit_fetch.write_manifest`：那个以 DOI 为轴（`- [ ] [10.xxxx](doi:...)`），
    知网条目套进去只会得到一堆空链接。这里按题名成行，人工照着查就行。
    """
    todo = [x for x in items if x.status not in ("ok", "skipped")]
    if not todo:
        return ""
    lines = ["# 知网残余清单（需人工）", "",
             f"生成：{bf._now()}　共 {len(todo)} 条　人工下载后放进 `{bf._rel(inbox)}`，",
             "再跑 `python tools/lit_manual_import.py --inbox \"<该目录>\" --apply` 收编。", ""]
    for x in todo:
        lines.append(f"- [ ] {x.title}")
        lines.append(f"  - 状态：`{x.status}`　原因：{x.reason or '—'}")
        if x.article_url_used:
            lines.append(f"  - 详情页：{x.article_url_used}")
    lines += ["", "> `blocked_format` = 只拿到 CAJ 且 caj2pdf 转不动（HN 格式等上游不支持），",
              "> 需要装 CAJViewer 打印或换数据库源；这类条目**不会**自动进 raw/pdf。", ""]
    bf._atomic_text(path, "\n".join(lines))
    return path


# ---------------------------------------------------------------------------
# 自检（不联网、不开浏览器）
# ---------------------------------------------------------------------------
def selftest() -> int:
    print("=== lit_cnki_fetch --selftest ===")
    ok = fail = 0

    def chk(name: str, cond: bool, extra: str = "") -> None:
        nonlocal ok, fail
        if cond:
            ok += 1
            print(f"  [OK]   {name}")
        else:
            fail += 1
            print(f"  [FAIL] {name} {extra}")

    # 1) URL 与主机判定
    chk("检索 URL 带 kw", "kw=" in cnki_search_url("固态电解质") and
        "%E5%9B%BA" in cnki_search_url("固态电解质"), cnki_search_url("固态电解质"))
    chk("检索 URL 带 dbCode", "dbCode=CDFD" in cnki_search_url("x", db="CDFD"))
    chk("识别 kns.cnki.net", is_cnki_url("https://kns.cnki.net/kns8s/defaultresult/index?kw=x"))
    chk("识别 r.cnki.com.cn", is_cnki_url("https://r.cnki.com.cn/x.pdf"))
    chk("拒非知网域", not is_cnki_url("https://example.com/cnki.net"))
    chk("学位论文老入口可用",
        "detail.aspx" in legacy_detail_url({"filename": "ABCD123.001", "dbcode": "CDFD"}))

    # 2) 题名规范化必须与 JS 侧同口径（JS: NFKC + 去 [\\s\\p{P}\\p{S}] + 小写）
    a = norm_title("  固态电解质-界面阻抗研究 ")
    b = norm_title("固态电解质——界面阻抗（研究）")
    chk("全半角/破折号/括号归一后相等", a == norm_title("固态电解质界面阻抗研究") == b,
        f"{a!r} vs {b!r}")
    chk("英文大小写归一", norm_title("Solid-State Electrolyte") == "solidstateelectrolyte")

    # 3) 墙分类
    w = classify_cnki_wall("https://kns.cnki.net/x", "知网登录", "请输入账号登录")
    chk("登录墙判为 paywalled", bool(w) and w["status"] == "paywalled", str(w))
    w2 = classify_cnki_wall("https://kns.cnki.net/x", "验证", "请按住滑块拖动完成拼图验证")
    chk("滑块墙判为需人工", bool(w2) and w2["status"] == "captcha_requires_human", str(w2))
    w3 = classify_cnki_wall("https://kns.cnki.net/x", "提示", "您所在单位未订购该数据库")
    chk("未订购判为 paywalled", bool(w3) and w3["status"] == "paywalled", str(w3))
    chk("正常页面不算墙", classify_cnki_wall("https://kns.cnki.net/x", "某论文", "摘要：本文研究…") is None)

    # 4) 下载候选打分/过滤
    cands = [{"url": "https://kns.cnki.net/x.html", "text": "HTML阅读"},
             {"url": "https://r.cnki.com.cn/ABCD.pdf", "text": "PDF下载"},
             {"url": "https://kns.cnki.net/caj/ABCD.caj", "text": "CAJ下载"},
             {"url": "https://kns.cnki.net/dl", "text": "整本下载"},
             {"url": "https://evil.example.com/a.pdf", "text": "PDF下载"}]
    pdfs = filter_candidates(cands, "pdf")
    chk("pdf 档只留 PDF", len(pdfs) == 1 and pdfs[0]["url"].endswith("ABCD.pdf"), str(pdfs))
    anyc = filter_candidates(cands, "any")
    chk("any 档按 PDF>下载>CAJ 排序",
        [x["url"] for x in anyc][:3] == ["https://r.cnki.com.cn/ABCD.pdf",
                                     "https://kns.cnki.net/dl",
                                     "https://kns.cnki.net/caj/ABCD.caj"], str(anyc))
    chk("外域候选被丢弃", all(is_cnki_url(x["url"]) for x in anyc))
    cajs = filter_candidates(cands, "caj")
    chk("caj 档只留 CAJ", len(cajs) == 1 and cajs[0]["ext"] == ".caj", str(cajs))

    # 5) 唯一命中判定
    links = [{"href": "https://kns.cnki.net/kcms2/article/abstract?v=1&filename=A.001&dbcode=CDFD",
              "text": "固态电解质界面阻抗研究", "filename": "A.001", "dbcode": "CDFD"},
             {"href": "https://kns.cnki.net/kns8s/Detail?filename=B.002", "text": "别的研究",
              "filename": "B.002", "dbcode": "CDFD"}]
    hit, why = pick_unique_match(links, "固态电解质——界面阻抗研究")
    chk("规范化后唯一命中", hit is not None, why)
    dup = links + [{"href": "https://kns.cnki.net/kns8s/Detail?filename=C.003",
                    "text": "固态电解质界面阻抗研究", "filename": "C.003", "dbcode": "CDFD"}]
    hit2, why2 = pick_unique_match(dup, "固态电解质界面阻抗研究")
    chk("同名多篇判为 ambiguous 不猜", hit2 is None and "ambiguous" in why2, why2)
    hit3, why3 = pick_unique_match(links, "根本没有这篇文章")
    chk("没有命中给出原因", hit3 is None and "no_exact_match" in why3, why3)

    # 6) 字节头猜测
    chk("%PDF- 判为 pdf", guess_ext(b"%PDF-1.7\n...", "https://x/y") == "pdf")
    chk("HTML 判为 html", guess_ext(b"<!DOCTYPE html><html>", "https://x/y") == "html")
    chk("URL 含 caj 判为 caj", guess_ext(b"\x00\x01", "https://x/a.caj") == "caj")
    chk("CAJ 容器头判为 caj", guess_ext(b"%TBS..." , "https://x/dl") == "caj")

    # 7) 题名清单解析
    parsed = titles_from_text(
        "# 待下载\n\n- 固态电解质界面研究\n* 锂金属负极\n"
        "  1. 硫化物电解质\n> 引用不要\n| 题名 | 刊名 |\n|---|---|\n"
        "| 氧化物电解质 | 物理化学学报 |\nhttps://doi.org/10.1/abc\n短\n")
    chk("清单解析出 4 条题名", len(parsed) == 4, str(parsed))
    chk("表格行取首格", "氧化物电解质" in parsed, str(parsed))
    chk("URL/短行被丢", all(len(p) >= 4 and not p.startswith("http") for p in parsed))

    # 8) 与既有链路的接缝
    chk("rate 域名已进默认配额表",
        RATE_DOMAIN in bf.DEFAULT_RATE_POLICY["per_domain_daily"],
        str(bf.DEFAULT_RATE_POLICY["per_domain_daily"]))
    chk("CAJ 默认目录在 _scratch 下", DEFAULT_CAJ_DIR_REL.startswith("_scratch/"))
    chk("CAJ 目录不在 raw/ 里", "raw/" not in DEFAULT_CAJ_DIR_REL)

    # 9) 报告与残余清单
    it1 = bf.Item(title="固态电解质界面研究", status="ok", dest=os.path.join(VAULT, "raw", "pdf", "x.pdf"))
    it2 = bf.Item(title="另一篇", status="failed", reason="blocked_format：上游不支持 HN")
    it2.article_url_used = "https://kns.cnki.net/x"
    rep = render_cnki_report([it1, it2], input_path="--selftest", mode="自检",
                             started=time.time(), inbox=os.path.join(VAULT, "raw/pdf"),
                             caj_dir=os.path.join(VAULT, "_scratch/lit-cnki-fetch/caj"))
    chk("报告含成功与待处理分区", "## ✅ 已入库候选" in rep and "## ❌ 待处理" in rep)
    chk("报告点明 CAJ 出口", "caj_to_pdf.py" in rep)
    txt = write_cnki_residual([it1, it2], os.path.join(VAULT, "_scratch", "selftest-residual.md"),
                              os.path.join(VAULT, "raw", "pdf"))
    body = bf._read_text(txt) if txt else ""
    chk("残余清单列出待人工条目", "另一篇" in body and "blocked_format" in body, txt)
    chk("全部成功时不写残余清单",
        write_cnki_residual([it1], os.path.join(VAULT, "_scratch", "selftest-residual2.md"),
                            os.path.join(VAULT, "raw", "pdf")) == "")
    for junk in ("selftest-residual.md", "selftest-residual2.md"):
        p = os.path.join(VAULT, "_scratch", junk)
        if os.path.exists(p):
            os.remove(p)

    # 10) R1 护栏：扫描上限与令牌抹除
    fake = [{"href": f"https://kns.cnki.net/kcms2/article/abstract?v={i}", "text": "无关题名"}
            for i in range(_RESULT_SCAN_CAP)]
    hit, why = pick_unique_match(fake, "固态电解质界面研究")
    chk("候选触顶时不判唯一（R1）", hit is None and "ambiguous" in why, why)
    one = [{"href": "https://kns.cnki.net/kns8s/Detail?filename=ABCD123", "text": "固态电解质界面研究"}]
    hit2, why2 = pick_unique_match(one, "固态电解质界面研究")
    chk("唯一命中照常放行", hit2 is not None, why2)
    m_cap = re.search(r"slice\(0,\s*(\d+)\)", JS_FIND_RESULT)
    chk("JS 扫描上限与 _RESULT_SCAN_CAP 同值",
        bool(m_cap) and int(m_cap.group(1)) == _RESULT_SCAN_CAP,
        m_cap.group(0) if m_cap else "JS 里没找到 slice")
    s_url = scrub_url("https://kns.cnki.net/kcms2/article/abstract"
                      "?v=S3CR3TT0KEN&filename=ABCD123&dbcode=CJFD")
    chk("会话令牌不进报告（R3）", "S3CR3TT0KEN" not in s_url and "v=<已隐去>" in s_url, s_url)
    chk("稳定标识保留便于人工复现",
        "filename=ABCD123" in s_url and "dbcode=CJFD" in s_url, s_url)

    # 配置布尔：YAML 里写成字符串时 bool() 会把 "false" 当 True
    chk('配置 "false" 判为关（不是 bool() 的开）', _cfg_bool("false", True, "t") is False)
    chk('配置 "0"/"关"/"no" 都判为关',
        all(_cfg_bool(x, True, "t") is False for x in ("0", "关", "no", "off")))
    chk('配置 "true"/"开"/1 判为开',
        all(_cfg_bool(x, False, "t") is True for x in ("true", "开", 1, True)))
    chk("认不出的值退回默认而不是瞎猜", _cfg_bool("maybe", True, "t") is True)
    chk("CAJ 原件默认保留（不再转成功就删原件）", "keep_caj" in resolve_opts(
        type("A", (), {"outdir": "", "si_dir": "", "cnki_url": "", "cnki_db": "",
                       "cnki_format": "", "no_caj_convert": False, "no_si": False,
                       "delete_caj": False})()).keys())
    m_big = re.search(r"u8\.length > (\d+)", JS_FETCH_BYTES)
    chk("JS 抓取上限与 MAX_CAJ_BYTES 同值（R：死常量不再骗人）",
        bool(m_big) and int(m_big.group(1)) == MAX_CAJ_BYTES,
        f"JS={m_big.group(1) if m_big else '?'} / 常量={MAX_CAJ_BYTES}")

    print(f"\n=== {ok}/{ok + fail} 通过 ===")
    return 0 if not fail else 2


# ---------------------------------------------------------------------------
# 主流程
# ---------------------------------------------------------------------------
def _cfg_bool(val: Any, default: bool, what: str = "") -> bool:
    """配置里的布尔要真解析：YAML/JSON 写成 `convert_caj: "false"` 时
    `bool("false")` 是 **True**，用户以为关了转换其实开着（反之亦然）。
    认得下的写法照认，认不出的**报出来**并退回默认值，不静默猜。
    """
    if val is None:
        return default
    if isinstance(val, bool):
        return val
    if isinstance(val, (int, float)) and val in (0, 1):
        return bool(val)
    if isinstance(val, str):
        s = val.strip().lower()
        if s in ("1", "true", "yes", "y", "on", "开", "是", "要"):
            return True
        if s in ("0", "false", "no", "n", "off", "关", "否", "不要"):
            return False
    print(f"[warn] 配置 {what or '布尔项'}=“{val}” 不是可识别的布尔，按 {default} 处理")
    return default


def resolve_opts(args) -> dict[str, Any]:
    """把 `lit_config.yaml` 的 `cnki` 段与命令行合到一起（命令行优先）。"""
    cfg: dict[str, Any] = {}
    try:
        import kb_lib as K
        cfg = K.load_lit_config() or {}
    except Exception as e:  # noqa: BLE001
        # 配置文件坏了不能静默当"没有配置"：里面的日配额、CAJ 目录全部失效，
        # 用户会以为还在限速内。报出来，让他知道这一轮跑的是内置默认。
        print(f"[warn] lit_config 读取失败（{type(e).__name__}: {e}）"
              f"，本轮使用内置默认参数")
        cfg = {}
    sec = cfg.get("cnki") or {}
    paths = cfg.get("paths") or {}
    pdf_dir = paths.get("pdf_dir") or os.path.join(VAULT, "raw", "pdf")
    inbox = bf._resolve(args.outdir or os.path.join(pdf_dir, "Manual Download"))
    si_dir = bf._resolve(args.si_dir) if getattr(args, "si_dir", "") else os.path.join(pdf_dir, "si")
    caj_rel = (sec.get("caj_dir") or DEFAULT_CAJ_DIR_REL).strip() or DEFAULT_CAJ_DIR_REL
    fmt = (getattr(args, "cnki_format", "") or sec.get("format") or "pdf").lower()
    if fmt not in ("pdf", "caj", "any"):
        print(f"[warn] cnki.format=“{fmt}” 不认识，按 pdf 处理")
        fmt = "pdf"
    return {
        "cfg": cfg, "pdf_dir": pdf_dir, "inbox": inbox, "si_dir": si_dir,
        "caj_dir": bf._resolve(caj_rel),
        "cnki_url": (getattr(args, "cnki_url", "") or sec.get("search_url")
                     or DEFAULT_CNKI_SEARCH),
        "cnki_db": (getattr(args, "cnki_db", "") or sec.get("db") or "").strip(),
        "cnki_format": fmt,
        "convert_caj": _cfg_bool(sec.get("convert_caj", True), True, "cnki.convert_caj") \
            and not getattr(args, "no_caj_convert", False),
        "keep_caj": not getattr(args, "delete_caj", False) \
            and _cfg_bool(sec.get("keep_caj", True), True, "cnki.keep_caj"),
        "no_si": bool(getattr(args, "no_si", False))
            or not _cfg_bool(sec.get("want_si", True), True, "cnki.want_si"),
    }


def cnki_items(args) -> tuple[list[Any], str]:
    """从 --title / --in 取题名清单；按规范化题名去重（知网没有 DOI 可去重）。"""
    titles = [t.strip() for t in (getattr(args, "title", None) or []) if t.strip()]
    if titles:
        items = [bf.Item(title=t, source="--title", recipe=RATE_DOMAIN) for t in titles]
        return _dedupe_by_title(items), "--title"
    if getattr(args, "input", ""):
        p = bf._resolve(args.input)
        return _dedupe_by_title(items_from_input(p)), p
    if getattr(args, "latest", False):
        p = bf.latest_input()
        return _dedupe_by_title(items_from_input(p)), p
    print("[错误] 知网模式需要 --title \"<题名>\" 或 --in <题名清单>"
          "（也支持 --latest 复用最近的 fetch_result）")
    raise SystemExit(2)


def _dedupe_by_title(items: list[Any]) -> list[Any]:
    seen: set[str] = set()
    out: list[Any] = []
    for it in items:
        key = norm_title(it.title)
        if not key or key in seen:
            continue
        seen.add(key)
        out.append(it)
    return out


def print_cnki_plan(items: list[Any], input_path: str, opts: dict[str, Any],
                    gov) -> None:
    print(f"[输入] {input_path}")
    print(f"[知网] 检索入口 {opts['cnki_url']}　格式 {opts['cnki_format']}　"
          f"CAJ 转换 {'开' if opts['convert_caj'] else '关'}　SI {'关' if opts['no_si'] else '开'}")
    print(f"[落点] 正文 {bf._rel(opts['inbox'])}　SI {bf._rel(opts['si_dir'])}　"
          f"未转换 CAJ {bf._rel(opts['caj_dir'])}")
    print(f"[计划] 待处理 {len(items)} 篇")
    for i, it in enumerate(items, 1):
        print(f"  {i:>2}. {it.title[:70]}")
    print(f"[rate] {gov.summary()}")


async def run_cnki(args, items: list[Any], input_path: str, started: float) -> int:
    """知网一轮：配额治理 → 逐篇抓取 → 可选收编 → 报告/残余/台账。

    与 `run_browser` 同构（同一 profile/锁/状态文件/配额/退出码），差别只有
    "配方"：那边按 DOI 选出版商，这边按题名走知网。
    """
    opts = resolve_opts(args)
    for d in (opts["inbox"], opts["si_dir"]):
        os.makedirs(d, exist_ok=True)

    profile = bf._resolve(args.profile)
    if args.fresh_profile:
        profile = profile + "-" + bf._now()
    lock = None
    if args.apply and not getattr(args, "no_lock", False):
        # 只在真要抓的时候抢锁：真跑进行中时，干跑也该能正常看一眼计划
        lock = bf.ProfileLock(os.path.join(os.path.dirname(profile), "profile.lock"))
        if not lock.acquire():
            return 2
    state_path = bf._resolve(args.state)
    try:
        state = bf._read_json(state_path)
        if not isinstance(state, dict):
            state = {}
    except Exception:  # noqa: BLE001
        state = {}
    domains = state.setdefault("domains", {})

    policy = bf.load_rate_policy(opts["cfg"])
    if getattr(args, "daily_total", 0):
        policy["daily_total"] = int(args.daily_total)
    per = policy.setdefault("per_domain_daily", {})
    per.setdefault(RATE_DOMAIN, 6)          # 配置缺失时的兜底，与代码默认一致
    gov = bf.RateGovernor(policy, domains, interactive=args.interactive,
                          enabled=not getattr(args, "no_rate_policy", False))
    opts["gov"] = gov                   # _grab_si 也要过节奏治理（SI 与正文各记一次）
    # 节奏治理是否真的在拦，必须在干跑第一屏就说清楚（lit_browser_fetch:2629 同法）：
    # 交互模式与 --no-rate-policy 都会让 precheck 直接放行，用户看不见就等于没这回事。
    if not getattr(gov, "enabled", True):
        print(f"[rate] 已按 --no-rate-policy 关闭节奏治理：{RATE_DOMAIN} 日配额 "
              f"{per.get(RATE_DOMAIN)}/日 **不生效**")
    elif args.interactive:
        print(f"[rate] 交互模式：节奏治理不拦（间隔/冷却/日配额全部放行）——"
              f"{RATE_DOMAIN} 配置值 {per.get(RATE_DOMAIN)}/日 仅作参考")
    else:
        print(f"[rate] {RATE_DOMAIN} 日配额 {per.get(RATE_DOMAIN)}/日，正文与 SI 各记一次")

    # 已在库的按题名先摘出去：知网条目没有 DOI，只能这样省一次全网检索
    pending: list[Any] = []
    for it in items:
        if not norm_title(it.title):
            it.status, it.reason = "skipped", "没有题名"
            continue
        found = find_existing_by_title(it.title)
        if found:
            it.status, it.dest = "skipped", found
            it.reason = "raw/pdf 已有题名匹配的真 PDF"
            continue
        pending.append(it)
    skipped = [x for x in items if x.status == "skipped"]
    if args.limit and args.limit > 0:
        pending = pending[:args.limit]

    print_cnki_plan(pending, input_path, opts, gov)
    for it in skipped[:5]:
        print(f"  ⏭️ {it.title[:50]} — {it.reason}")
    if len(skipped) > 5:
        print(f"  ⏭️ … 另有 {len(skipped) - 5} 篇跳过")
    if not args.apply:
        print("\n[提示] 当前是干跑；加 --apply 才会真正启动浏览器下载。")
        if lock is not None:
            lock.release()
        return 0
    if not pending:
        print("[完成] 没有待处理项")
        if lock is not None:
            lock.release()
        return 0

    session = bf.BrowserSession(profile, headless=args.headless,
                                interactive=args.interactive,
                                human_timeout=args.human_timeout,
                                channel=args.channel,
                                delay_min=args.delay_min, delay_max=args.delay_max)
    try:
        await session.launch()
    except Exception as e:  # noqa: BLE001
        print(f"[错误] 浏览器启动失败：{e}")
        if lock is not None:
            lock.release()
        return 2

    # 预筛摘出去的（库里已有 / 没有题名）也必须进报告与 JSON。
    # 原来只把"跑过一遍"的放进 results，报告就永远写「跳过 0」：
    # 用户给 20 篇、报告说处理 3 篇，凭空少 17 篇，正是本 skill 最忌讳的静默变差。
    results: list[Any] = list(skipped)
    try:
        page = None
        for idx, it in enumerate(pending, 1):
            blocked = gov.precheck(RATE_DOMAIN)
            if blocked:
                it.status, it.reason = "skipped", blocked
                results.append(it)
                print(f"[hold] cnki：{blocked} → 推迟《{it.title[:40]}》")
                continue
            wait = gov.wait_seconds(RATE_DOMAIN)
            if wait > 0:
                print(f"[wait] cnki 节奏：等 {wait:.0f}s")
                await asyncio.sleep(wait)
            if page is None or page.is_closed():
                try:
                    page = await session.ctx.new_page()
                except Exception as e:  # noqa: BLE001
                    if await session.ensure_ready():
                        try:
                            page = await session.ctx.new_page()
                        except Exception:  # noqa: BLE001
                            page = None
                    if page is None:
                        it.status, it.reason = "failed", f"浏览器不可用：{type(e).__name__}"
                        results.append(it)
                        continue
            print(f"\n[{idx}/{len(pending)}] 《{it.title[:60]}》")
            try:
                await fetch_one(session, page, it, opts)
            except Exception as e:  # noqa: BLE001
                it.status = it.status or "failed"
                it.reason = it.reason or f"{type(e).__name__}: {str(e)[:140]}"
            outcome = ("ok" if it.status == "ok"
                       else "challenge" if it.status in bf.CHALLENGE_STATES
                       else "other")
            gov.note(RATE_DOMAIN, outcome, it.reason or "")
            mark = {"ok": "✅", "skipped": "⏭️"}.get(it.status, "❌")
            print(f"  {mark} {it.status} — {(it.reason or it.dest or '')[:110]}")
            results.append(it)
            try:
                bf._atomic_text(state_path, json.dumps(state, ensure_ascii=False, indent=1))
            except Exception:  # noqa: BLE001
                pass
            if idx < len(pending):
                await session.polite_sleep()
        try:
            await page.close()
        except Exception:  # noqa: BLE001
            pass
    finally:
        if getattr(args, "keep_open", False):
            print("\n[keep-open] 浏览器保持打开；关闭窗口后脚本退出。")
        await session.close(keep_processes=getattr(args, "keep_open", False))
        if lock is not None:
            lock.release()
        try:
            bf._atomic_text(state_path, json.dumps(state, ensure_ascii=False, indent=1))
        except Exception:  # noqa: BLE001
            pass

    # ---- 收编：与英文链路同一个入口，只有真 PDF 会走到这里 ----
    if args.import_:
        print("\n[import] 运行 lit_manual_import.py --apply ...")
        try:
            env = dict(os.environ, PYTHONIOENCODING="utf-8")
            cp = subprocess.run([sys.executable, os.path.join(HERE, "lit_manual_import.py"),
                                 "--inbox", opts["inbox"], "--apply"],
                                cwd=VAULT, capture_output=True, text=True,
                                encoding="utf-8", errors="replace", timeout=900, env=env)
            tail = (cp.stdout or "")[-1500:]
            if tail:
                print(tail)
            if cp.returncode != 0:
                print(f"[warn] lit_manual_import 退出码 {cp.returncode}：{(cp.stderr or '')[-400:]}")
        except Exception as e:  # noqa: BLE001
            print(f"[warn] 收编失败：{type(e).__name__}: {e}")

    # ---- 报告 ----
    stamp = bf._now()
    if args.report:
        report_path = bf._resolve(args.report)
        report_dir = os.path.dirname(report_path) or "."
        stem = os.path.splitext(os.path.basename(report_path))[0]
    else:
        report_dir = bf._resolve("raw/notes/lit-watch/downloads")
        stem = f"cnki-fetch-{stamp}"
        report_path = os.path.join(report_dir, stem + ".md")
    os.makedirs(report_dir, exist_ok=True)
    residual_path = os.path.join(report_dir, f"{stem}-residual.md")
    residual = "" if getattr(args, "no_residual", False) else \
        write_cnki_residual(results, residual_path, opts["inbox"])
    mode = ("apply/交互" if args.interactive else "apply/无人值守") if args.apply else "干跑"
    bf._atomic_text(report_path, render_cnki_report(
        results, input_path=input_path, mode=mode, started=started,
        inbox=opts["inbox"], caj_dir=opts["caj_dir"], residual_path=residual))
    bf._atomic_text(os.path.join(report_dir, stem + ".json"),
                    json.dumps([bf.asdict(x) for x in results],
                               ensure_ascii=False, indent=1))
    print(f"\n[report] {bf._rel(report_path)}")
    if residual:
        print(f"[residual] {bf._rel(residual)}")
    else:
        print("[residual] 0 条——本批不需要人工")
    ok_n = sum(1 for x in results if x.status == "ok")
    si_n = sum(1 for x in results if x.si_status == "present")
    if not getattr(args, "no_log", False):
        bf.append_log(f"## [{bf._today()}] lit-cnki-fetch | 输入 `{input_path}`："
                      f"知网正文成功 {ok_n}/{len(results)}，SI {si_n} 篇，"
                      f"残余 `{bf._rel(residual) if residual else '无'}`")
    return bf.exit_code_for(results)


def add_arguments(ap) -> None:
    """知网专属开关。`lit_browser_fetch.build_parser()` 也会调用它——
    这样"一个入口"不是口号：同一份 help、同一套 profile/配额参数。"""
    g = ap.add_argument_group("知网 CNKI（--source cnki）")
    g.add_argument("--source", default="auto", choices=["auto", "publisher", "cnki"],
                   help="auto=有 --title 即走知网，否则按 DOI 走出版商（默认）")
    g.add_argument("--title", action="append", default=[],
                   help="知网检索题名（可重复；题名而非 DOI 是知网的入口）")
    g.add_argument("--cnki-format", default="", choices=["", "pdf", "caj", "any"],
                   help="下载格式偏好（默认读 lit_config.yaml 的 cnki.format，缺省 pdf）")
    g.add_argument("--cnki-url", default="", help="检索入口（默认 kns8s 结果页）")
    g.add_argument("--cnki-db", default="", help="限定数据库代码，如 CDFD 期刊 / CDFW 学位论文")
    g.add_argument("--no-caj-convert", action="store_true",
                   help="拿到 CAJ 不转换，原件留在 _scratch 里等手工")
    g.add_argument("--delete-caj", action="store_true",
                   help="转换成功后删掉 CAJ 原件（默认**保留**在 _scratch 以便日后重转）")


def main(argv: Optional[list[str]] = None) -> int:
    """单独跑时也走同一个入口：注入 --source cnki 后交给 lit_browser_fetch。

    `--selftest` 例外——那必须跑**本模块**的自检（知网纯函数层），
    不能悄悄转发成出版商那条链路的自检，否则"自检通过"是假的。
    """
    argv = list(sys.argv[1:] if argv is None else argv)
    if "--selftest" in argv:
        return selftest()
    if "--source" not in argv:
        argv += ["--source", "cnki"]
    return bf.main(argv)


if __name__ == "__main__":
    raise SystemExit(main())
